      "content": "import { expect, test } from 'bun:test';
import { OperatorRuntime, type UseCaseInstances } from '@agentic-ddd/runtime';
import { covers, FakeLlm, InMemoryEventBus } from '@agentic-ddd/testing';
import { CompleteTask } from '../application/complete-task';
import { CreateTask } from '../application/create-task';
import { TaskCompleted, TaskCreated } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
import { TaskOperator } from '../operators/task.operator';

test(covers([
  'operator:task-operator',
  'criterion:0001/tools',
], 'cria e conclui t1 somente pelas duas tools e publica os dois eventos'), async () => {
  const repository = new InMemoryTaskRepository();
  const eventBus = new InMemoryEventBus();
  const llm = new FakeLlm([
    {
      content: [{
        type: 'tool_call', id: 'create-t1', name: 'create_task',
        input: { task_id: 't1', title: '  Comprar pão  ' },
      }],
      stopReason: 'tool_calls',
    },
    {
      content: [{
        type: 'tool_call', id: 'complete-t1', name: 'complete_task',
        input: { task_id: 't1' },
      }],
      stopReason: 'tool_calls',
    },
    {
      content: [{ type: 'text', text: 'A tarefa t1 foi criada e concluída.' }],
      stopReason: 'end',
    },
  ]);
  const runtime = new OperatorRuntime({
    llm, eventBus,
    root: new URL('../../', import.meta.url).pathname,
    modules: [{ name: 'tasks', path: 'app' }],
  });
  const instances: UseCaseInstances = new Map<typeof CreateTask | typeof CompleteTask, CreateTask | CompleteTask>([
    [CreateTask, new CreateTask(repository)],
    [CompleteTask, new CompleteTask(repository)],
  ]);
  await runtime.register(TaskOperator, instances);

  const message = 'Crie a tarefa t1 com título Comprar pão e conclua a tarefa t1.';
  const result = await runtime.run('task-operator', { message });

  expect(result.status).toBe('completed');
  expect(result.operator).toBe('task-operator');
  expect(result.output).toBe('A tarefa t1 foi criada e concluída.');
  expect(llm.requests).toHaveLength(3);
  expect(llm.requests[0]!.messages).toEqual([{ role: 'user', text: message }]);
  for (const request of llm.requests) {
    expect(request.tools.map(tool => tool.name).sort()).toEqual(['complete_task', 'create_task']);
    expect(request.system).toContain('Identifique a tarefa pelo id e responda em português.');
  }
  expect(result.steps).toHaveLength(3);
  const tools = result.steps.flatMap(step => step.tools);
  expect(tools.map(tool => tool.call.name)).toEqual(['create_task', 'complete_task']);
  expect(tools.map(tool => tool.policy)).toEqual(['allow', 'allow']);
  expect(tools.map(tool => tool.result)).toEqual([
    {
      toolCallId: 'create-t1', isError: false,
      content: {
        output: { task_id: 't1', title: 'Comprar pão', status: 'pending' },
        events: [{ name: 'TaskCreated', payload: { taskId: 't1', title: 'Comprar pão' } }],
      },
    },
    {
      toolCallId: 'complete-t1', isError: false,
      content: {
        output: { task_id: 't1', status: 'completed' },
        events: [{ name: 'TaskCompleted', payload: { taskId: 't1' } }],
      },
    },
  ]);
  expect(llm.requests[2]!.messages.filter(message => message.role === 'tool')).toEqual([
    { role: 'tool', results: [tools[0]!.result!] },
    { role: 'tool', results: [tools[1]!.result!] },
  ]);
  const saved = await repository.findById('t1');
  expect(saved).not.toBeNull();
  expect(saved?.title).toBe('Comprar pão');
  expect(saved?.status).toBe('completed');
  expect(saved?.pullEvents()).toEqual([]);
  expect(eventBus.events).toHaveLength(2);
  expect(eventBus.events[0]).toBeInstanceOf(TaskCreated);
  expect(eventBus.events[0]!.payload).toEqual({ taskId: 't1', title: 'Comprar pão' });
  expect(eventBus.events[1]).toBeInstanceOf(TaskCompleted);
  expect(eventBus.events[1]!.payload).toEqual({ taskId: 't1' });
  expect(result.events).toEqual(eventBus.events);
  expect(tools.map(tool => tool.events)).toEqual([
    [eventBus.events[0]], [eventBus.events[1]],
  ]);
});
